SELECT t.tdocNumber,t.title,a.resolutionId,m.meetingNumber FROM Agreement a JOIN rel_REFERENCES r ON r.src_id=a.node_id JOIN Tdoc t ON t.node_id=r.dst_id JOIN rel_SUBMITTED_BY s ON s.src_id=t.node_id JOIN Company c ON c.node_id=s.dst_id JOIN rel_MADE_AT ma ON ma.src_id=a.node_id JOIN Meeting m ON m.node_id=ma.dst_id WHERE c.companyName='Huawei' AND owned_reference(a.content,t.tdocNumber)=1 ORDER BY m.meetingNumberInt DESC,t.tdocNumber,a.resolutionId
